<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans;font-size:12px;color:#222}.head{border:2px solid #111;padding:16px}.letter{font-size:30px;text-align:center;font-weight:bold}.cols{width:100%}.cols td{width:50%;vertical-align:top}.items{width:100%;border-collapse:collapse;margin-top:20px}.items th,.items td{border:1px solid #777;padding:8px}.right{text-align:right}.total{font-size:16px;font-weight:bold}.footer{margin-top:25px}.qr{width:125px}</style></head><body><div class="head"><table class="cols"><tr><td><h2>{{ $invoice->profile->business_name }}</h2>{{ $invoice->profile->address }}<br>CUIT: {{ $invoice->profile->cuit }}<br>{{ $invoice->profile->vat_condition }}</td><td><div class="letter">{{ $invoice->invoice_type }}</div><strong>FACTURA ELECTRÓNICA</strong><br>Punto de venta: {{ str_pad($invoice->profile->sales_point,5,'0',STR_PAD_LEFT) }}<br>Comprobante: {{ str_pad($arca['number'],8,'0',STR_PAD_LEFT) }}<br>Fecha: {{ date('d/m/Y',strtotime($arca['date'])) }}</td></tr></table></div><h3>Cliente</h3><p><strong>{{ $payload['customer']['name'] }}</strong><br>{{ $payload['customer']['address'] }}<br>{{ $payload['customer']['vat_condition'] }} · Documento {{ $payload['customer']['document_number'] }}</p><table class="items"><thead><tr><th>Descripción</th><th>Cantidad</th><th>Precio unitario</th><th>Total</th></tr></thead><tbody>@foreach($payload['items'] as $item)<tr><td>{{ $item['description'] }}</td><td class="right">{{ $item['quantity'] }}</td><td class="right">$ {{ number_format($item['unit_price'],2,',','.') }}</td><td class="right">$ {{ number_format($item['quantity']*$item['unit_price'],2,',','.') }}</td></tr>@endforeach</tbody></table><p class="right total">Total: $ {{ number_format($arca['total'],2,',','.') }}</p><table class="cols footer"><tr><td><img class="qr" src="{{ $qr }}"></td><td><strong>CAE:</strong> {{ $arca['cae'] }}<br><strong>Vencimiento CAE:</strong> {{ date('d/m/Y',strtotime($arca['cae_expires_at'])) }}<br><small>Comprobante autorizado por ARCA.</small></td></tr></table></body></html>
